SELECT p.subject_id, CAST(COUNT(DISTINCT CASE WHEN ph.drug = 'GLP‑1 RA' AND ph.starttime BETWEEN a.admittime AND a.dischtime THEN ph.pharmacy_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT ph.pharmacy_id), 0) AS proportion_glp_1_ra, COUNT(DISTINCT CASE WHEN ph.drug = 'GLP‑1 RA' AND ph.starttime BETWEEN a.admittime AND a.dischtime THEN ph.pharmacy_id END) AS num_glp_1_ra, COUNT(DISTINCT ph.pharmacy_id) AS total_pharmacies FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN prescriptions ph ON p.subject_id = ph.subject_id AND a.hadm_id = ph.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 57 AND 67 AND p.subject_id IN (SELECT subject_id FROM diagnoses_icd WHERE icd_code IN ('440.0', '440.1')) GROUP BY p.subject_id ORDER BY proportion_glp_1_ra DESC NULLS LAST;